<title>{{ $masjid->name }} · BayanDigital</title>
<style>
:root{--emerald:#08735b;--deep:#062d28;--mint:#e8f8f2;--gold:#f2bd4b;--ink:#102c27;--muted:#61746f;--line:#dce9e4;--paper:#f6faf8}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 Inter,ui-sans-serif,system-ui,sans-serif}a{color:inherit}.wrap{width:min(1160px,calc(100% - 40px));margin:auto}.nav{position:sticky;top:0;z-index:20;color:white;background:rgba(5,40,35,.94);backdrop-filter:blur(16px);border-bottom:1px solid #ffffff1c}.nav-inner{height:72px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{display:flex;align-items:center;gap:11px;font-weight:900;text-decoration:none;min-width:0}.brand img{width:42px;height:42px;border-radius:12px;background:white;padding:4px;object-fit:contain}.brand span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.menu{display:flex;align-items:center;gap:5px}.menu a{padding:9px 12px;border-radius:10px;text-decoration:none;font-size:.88rem;font-weight:750}.menu a:hover,.menu a:focus{background:#ffffff17}.hero{position:relative;overflow:hidden;color:white;background:radial-gradient(circle at 80% 15%,#2bb89155,transparent 30%),linear-gradient(135deg,#052e29,#08735b);padding:80px 0 96px}.hero:after{content:"";position:absolute;inset:auto -10% -160px;height:250px;background:var(--paper);border-radius:50% 50% 0 0}.hero-grid{position:relative;z-index:1;display:grid;grid-template-columns:1.45fr .75fr;align-items:center;gap:60px}.kicker{text-transform:uppercase;letter-spacing:.18em;color:#9cf0d7;font-size:.78rem;font-weight:900}.hero h1{max-width:760px;margin:8px 0 14px;font-size:clamp(2.4rem,6vw,5.2rem);line-height:1.02;letter-spacing:-.055em}.address{max-width:650px;color:#d8eee8;white-space:pre-line}.hero-logo{width:min(280px,100%);aspect-ratio:1;border-radius:36px;background:#fff;padding:22px;object-fit:contain;box-shadow:0 30px 80px #001d1866;transform:rotate(2deg)}.notice-stack{position:relative;z-index:2;margin-top:-42px}.notice{display:flex;gap:16px;align-items:flex-start;margin-bottom:12px;padding:19px 22px;border:1px solid #f3c56f;background:#fff9e9;border-radius:18px;box-shadow:0 14px 40px #102c2712}.notice-icon{display:grid;place-items:center;flex:0 0 42px;width:42px;height:42px;border-radius:12px;color:white;background:#c47713;font-weight:900}.notice h2{margin:0;font-size:1.04rem}.notice p{margin:3px 0 0;color:#665536}.section{padding:72px 0}.section.alt{background:white}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:28px}.section-head h2{margin:0;font-size:clamp(1.8rem,4vw,2.7rem);letter-spacing:-.04em}.section-head p{max-width:580px;margin:0;color:var(--muted)}.prayers{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:12px}.prayer{position:relative;overflow:hidden;padding:22px 14px;text-align:center;border:1px solid var(--line);border-radius:18px;background:white;box-shadow:0 10px 35px #0b493b0a}.prayer:before{content:"";position:absolute;inset:0 0 auto;height:4px;background:var(--emerald)}.prayer strong,.prayer span{display:block}.prayer strong{text-transform:uppercase;letter-spacing:.09em;color:var(--muted);font-size:.72rem}.prayer span{margin-top:5px;color:var(--emerald);font-size:1.5rem;font-weight:900}.content-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.story{padding:25px;border:1px solid var(--line);border-radius:20px;background:white;box-shadow:0 12px 35px #102c270a}.story h3{margin:0 0 8px;font-size:1.2rem}.story p{margin:0;color:var(--muted)}.schedule{display:grid;grid-template-columns:120px 1fr;overflow:hidden;border:1px solid var(--line);border-radius:22px;background:white}.schedule-image,.schedule-placeholder{width:120px;height:100%;min-height:170px}.schedule-image{object-fit:cover}.schedule-placeholder{display:grid;place-items:center;color:white;background:linear-gradient(145deg,var(--emerald),var(--deep));font-size:2.2rem}.schedule-body{padding:23px}.schedule-body h3{margin:0 0 6px}.schedule-body p{margin:0;color:var(--muted);white-space:pre-line}.side-grid{display:grid;grid-template-columns:1.4fr .8fr;gap:24px}.committee{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.member{display:flex;align-items:center;gap:13px;padding:16px;border:1px solid var(--line);border-radius:16px;background:white}.member-photo,.member-initial{flex:0 0 55px;width:55px;height:55px;border-radius:50%}.member-photo{object-fit:cover}.member-initial{display:grid;place-items:center;color:white;background:var(--emerald);font-size:1.25rem;font-weight:900}.member-position{display:block;color:var(--emerald);font-size:.84rem}.member-contact{display:flex;gap:9px;font-size:.78rem}.donation{text-align:center;padding:26px;border-radius:24px;color:white;background:linear-gradient(145deg,var(--deep),var(--emerald))}.qr{display:block;width:min(230px,100%);aspect-ratio:1;object-fit:contain;margin:16px auto;border-radius:18px;background:white;padding:10px}.qr-placeholder{display:grid;place-items:center;color:var(--ink);font-weight:900}.footer{padding:35px 0;color:#cde7df;background:#052e29}.footer-inner{display:flex;justify-content:space-between;gap:20px}.empty{grid-column:1/-1;padding:28px;border:1px dashed #a9c7bd;border-radius:18px;color:var(--muted);text-align:center}@media(max-width:850px){.menu{display:none}.hero{padding:55px 0 80px}.hero-grid,.side-grid{grid-template-columns:1fr}.hero-logo{display:none}.content-grid,.committee{grid-template-columns:1fr}.section{padding:52px 0}.section-head{display:block}.section-head p{margin-top:7px}}@media(max-width:520px){.wrap{width:min(100% - 24px,1160px)}.schedule{grid-template-columns:90px 1fr}.schedule-image,.schedule-placeholder{width:90px}.footer-inner{display:block}}
</style></head><body>
