<main>
<section class="section" id="prayer-times"><div class="wrap"><div class="section-head"><div><div class="kicker" style="color:var(--emerald)">Daily worship</div><h2>Today's prayer times</h2></div><p>Prayer timetable for {{ $masjid->zone_code }}. Please refer to the mosque screen for iqamah countdowns.</p></div><div class="prayers">@foreach($prayerTime->times as $name => $time)<div class="prayer"><strong>{{ ucfirst($name) }}</strong><span>{{ $time }}</span></div>@endforeach</div></div></section>
<section class="section alt" id="announcements"><div class="wrap"><div class="section-head"><div><div class="kicker" style="color:var(--emerald)">Stay informed</div><h2>Announcements</h2></div><p>Latest information published directly by the {{ $masjid->type }} administration.</p></div><div class="content-grid">@forelse($announcements as $announcement)<article class="story"><h3>{{ $announcement->title ?: 'Community update' }}</h3><p>{!! nl2br(e($announcement->body)) !!}</p></article>@empty<div class="empty">There are no current announcements.</div>@endforelse</div></div></section>
<section class="section" id="programmes"><div class="wrap"><div class="section-head"><div><div class="kicker" style="color:var(--emerald)">Learn together</div><h2>Jadual Ustaz</h2></div><p>Classes, kuliah and weekly teaching schedules maintained from the same admin panel as the Android display.</p></div><div class="content-grid">@forelse($schedules as $schedule)<article class="schedule">@if($schedule->media_path)<img class="schedule-image" src="{{ $schedule->media_path }}" alt="{{ $schedule->title ?: 'Ustaz' }}">@else<div class="schedule-placeholder" aria-hidden="true">◷</div>@endif<div class="schedule-body"><h3>{{ $schedule->title ?: 'Jadual Ustaz' }}</h3><p>{{ $schedule->body }}</p></div></article>@empty<div class="empty">The ustaz programme schedule will be published here soon.</div>@endforelse</div></div></section>
<section class="section alt" id="community"><div class="wrap side-grid"><div><div class="section-head"><div><div class="kicker" style="color:var(--emerald)">People who serve</div><h2>Committee</h2></div></div><div class="committee">@forelse($committeeMembers as $member)<article class="member">@if($member->photo_path)<img class="member-photo" src="{{ Storage::url($member->photo_path) }}" alt="Photo of {{ $member->name }}">@else<div class="member-initial">{{ Str::upper(Str::substr($member->name, 0, 1)) }}</div>@endif<div><strong>{{ $member->name }}</strong><span class="member-position">{{ $member->position }}</span>@if(($member->show_phone_publicly && $member->phone) || ($member->show_email_publicly && $member->email))<div class="member-contact">@if($member->show_phone_publicly && $member->phone)<a href="tel:{{ preg_replace('/[^+0-9]/', '', $member->phone) }}">Call</a>@endif @if($member->show_email_publicly && $member->email)<a href="mailto:{{ $member->email }}">Email</a>@endif</div>@endif</div></article>@empty<div class="empty">Committee details are coming soon.</div>@endforelse</div></div>
<aside class="donation" id="donations"><div class="kicker">Support the community</div><h2>Donations</h2>@if($donationQrUrl)<img class="qr" src="{{ $donationQrUrl }}" alt="Donation QR code for {{ $masjid->name }}">@else<div class="qr qr-placeholder">QR NOT CONFIGURED</div>@endif<p>{{ $masjid->donation_caption ?: 'Scan to support '.$masjid->name.'.' }}</p>@if($masjid->donation_account)<strong>{{ $masjid->donation_account }}</strong>@endif</aside></div></section>
